<script setup>
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import EnrollmentLoad from './EnrollmentLoad.vue'
import EnrollmentDialog from './EnrollmentDialog.vue'
import { apiClient } from '../../services/apiClient'
import { classifications, label, termLabel, safeError } from './enrollment'
const route=useRoute(), periodsPage=computed(()=>route.name==='enrollment-periods')
const data=ref(null), busy=ref(false), error=ref(''), notice=ref(''), detail=ref(null), requirements=ref([]), notes=ref(''), confirmation=ref(''), form=ref(null), yearForm=ref(null), page=ref(1)
const filters=ref({search:'',course_id:'',classification:'',status:'',period_id:'',sort:'newest'})
let epoch=0
const rows=computed(()=>periodsPage.value?data.value?.periods:data.value?.applications)
const profileOf=item=>item?.student?.user_profile || item?.owner?.profile
const nameOf=item=>[profileOf(item)?.first_name,profileOf(item)?.last_name].filter(Boolean).join(' ') || 'Applicant'
const identityOf=item=>item?.student?.student_number || item?.admission_applicant?.applicant_number || 'Student number pending'
const applicantType=item=>item?.student ? 'Student' : 'First-time admitted Guest'
async function load() {
 const v=++epoch;busy.value=true;error.value=''
 try{const r=await apiClient.get(periodsPage.value?'/enrollment/periods':'/enrollment/applications',{params:{...filters.value,page:page.value}});if(v===epoch)data.value=r.data.data}
 catch(e){if(v===epoch)error.value=safeError(e)}finally{if(v===epoch)busy.value=false}
}
async function inspect(a) {
 const v=++epoch;busy.value=true;error.value=''
 try{const r=await apiClient.get(`/enrollment/applications/${a.id}`);if(v!==epoch)return;detail.value=r.data.data.application;requirements.value=r.data.data.requirements;notes.value=detail.value.review_notes||''}
 catch(e){if(v===epoch)error.value=safeError(e)}finally{if(v===epoch)busy.value=false}
}
async function act() {
 if(busy.value)return;const action=confirmation.value;confirmation.value='';const v=++epoch;busy.value=true;error.value=''
 try{await apiClient.post(`/enrollment/applications/${detail.value.id}/${action}`,{version:detail.value.version,notes:notes.value,confirmed:true});if(v!==epoch)return;notice.value='Application updated.';await inspect(detail.value);await load()}
 catch(e){if(v===epoch)error.value=safeError(e)}finally{if(v===epoch)busy.value=false}
}
function closeDetail() {
 if(busy.value)return;detail.value=null;requirements.value=[];notes.value='';confirmation.value=''
}
async function refreshDetail() {
 if(!detail.value)return;await inspect(detail.value);await load()
}
const localDate=value=>{if(!value)return '';const d=new Date(value);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
const requirementConfig=value=>Array.isArray(value)?{required:[...value],optional:[]}:{required:[...(value?.required||[])],optional:[...(value?.optional||[])]}
const normalizeRequirements=requirements=>Object.fromEntries(classifications.map(c=>[c.value,requirementConfig(requirements?.[c.value])]))
function edit(p) { form.value=p?{...p,opens_at:localDate(p.opens_at),closes_at:localDate(p.closes_at),document_requirements:normalizeRequirements(p.document_requirements)}:{academic_year_id:'',semester_id:'',opens_at:'',closes_at:'',enabled:false,document_requirements:normalizeRequirements({})} }
function editYear(year=null){yearForm.value=year?{...year,start_date:String(year.start_date).slice(0,10),end_date:String(year.end_date).slice(0,10)}:{school_year:'',start_date:'',end_date:'',status:'upcoming'}}
async function saveYear(){if(busy.value)return;const v=++epoch;busy.value=true;error.value='';try{const payload={...yearForm.value};const id=payload.id;delete payload.id;delete payload.created_at;delete payload.updated_at;if(id)await apiClient.put(`/enrollment/academic-years/${id}`,payload);else await apiClient.post('/enrollment/academic-years',payload);if(v!==epoch)return;yearForm.value=null;notice.value='Academic year saved.';await load()}catch(e){if(v===epoch)error.value=safeError(e)}finally{if(v===epoch)busy.value=false}}
async function savePeriod() {
 if(busy.value)return;const v=++epoch;busy.value=true;error.value=''
 try {const payload={...form.value,academic_year_id:Number(form.value.academic_year_id),semester_id:Number(form.value.semester_id),opens_at:new Date(form.value.opens_at).toISOString(),closes_at:new Date(form.value.closes_at).toISOString()};
 if(form.value.id)await apiClient.put(`/enrollment/periods/${form.value.id}`,payload);else await apiClient.post('/enrollment/periods',payload);if(v!==epoch)return;form.value=null;notice.value='Enrollment period saved.';await load()}
 catch(e){if(v===epoch)error.value=safeError(e)}finally{if(v===epoch)busy.value=false}
}
async function download(d) {
 const v=epoch;error.value=''
 try {const r=await apiClient.get(`/enrollment/applications/${detail.value.id}/documents/${d.document_id}`,{responseType:'blob'});if(v!==epoch)return;const url=URL.createObjectURL(r.data);const link=document.createElement('a');link.href=url;link.download=`${d.name}.${({'application/pdf':'pdf','image/png':'png','image/jpeg':'jpg'})[r.data.type] || 'bin'}`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(v===epoch)error.value=safeError(e)}
}
watch(()=>route.name,()=>{data.value=null;detail.value=null;form.value=null;yearForm.value=null;confirmation.value='';page.value=1;load()})
onMounted(load);onBeforeUnmount(()=>{epoch++})
</script>
<template>
<header class="page-header"><p class="page-kicker">Enrollment</p><h1 class="page-title">{{ periodsPage?'Enrollment Periods':'Applications' }}</h1><p class="page-description">{{ periodsPage?'Manage when Students can apply for an academic term.':'Review enrollment applications before academic finalization.' }}</p></header>
<nav class="en-actions" aria-label="Enrollment workspace"><RouterLink class="en-link" to="/enrollment/applications">Applications</RouterLink><RouterLink class="en-link" to="/enrollment/periods">Enrollment Periods</RouterLink></nav>
<p v-if="error" class="en-card" role="alert">{{ error }} <button :disabled="busy" @click="detail?inspect(detail):load()">Reload</button></p><p v-if="notice" role="status">{{ notice }}</p><p v-if="busy" role="status">Loading…</p>
<template v-if="data">
<template v-if="periodsPage">
<div class="en-actions"><button :disabled="busy" @click="editYear()">Add academic year</button><button :disabled="busy" @click="edit(null)">Create period</button></div>
<form v-if="yearForm" class="en-card" @submit.prevent="saveYear"><h2>{{ yearForm.id?'Edit academic year':'Add academic year' }}</h2><div class="en-grid"><label>School year<input v-model.trim="yearForm.school_year" pattern="\d{4}-\d{4}" placeholder="2027-2028" required></label><label>Starts<input v-model="yearForm.start_date" type="date" required></label><label>Ends<input v-model="yearForm.end_date" type="date" required></label><label>Status<select v-model="yearForm.status" required><option value="upcoming">Upcoming</option><option value="active">Active</option><option value="completed">Completed</option></select></label></div><p>Only one academic year can be active. Referenced year labels and dates remain historical.</p><div class="en-actions"><button :disabled="busy" type="submit">Save academic year</button><button :disabled="busy" type="button" class="en-secondary" @click="yearForm=null">Cancel</button></div></form>
<section class="en-card"><h2>Academic years</h2><div class="en-table"><table><thead><tr><th>School year</th><th>Dates</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="year in data.academic_years" :key="year.id"><td>{{ year.school_year }}</td><td>{{ String(year.start_date).slice(0,10) }} – {{ String(year.end_date).slice(0,10) }}</td><td><span class="en-badge" :data-status="year.status">{{ label(year.status) }}</span></td><td><button :disabled="busy" @click="editYear(year)">Edit</button></td></tr></tbody></table></div></section>
<form v-if="form" class="en-card" @submit.prevent="savePeriod"><h2>{{ form.id?'Edit period':'Create enrollment period' }}</h2><div class="en-grid"><label>Academic year<select v-model="form.academic_year_id" :disabled="!!form.id || busy" required><option value="">Choose year</option><option v-for="y in data.academic_years" :key="y.id" :value="y.id">{{ y.school_year }}</option></select></label><label>Semester<select v-model="form.semester_id" :disabled="!!form.id || busy" required><option value="">Choose semester</option><option v-for="s in data.semesters" :key="s.id" :value="s.id">{{ s.semester_name }}</option></select></label><label>Opens at (your local time)<input type="datetime-local" v-model="form.opens_at" required :disabled="busy"></label><label>Closes at (your local time)<input type="datetime-local" v-model="form.closes_at" required :disabled="busy"></label></div>
<label class="en-check"><input type="checkbox" v-model="form.enabled" :disabled="busy"> Enable period</label><p>Enabled periods open and close according to backend time. Disable a period to close it immediately. To reopen it, enable it with a current opening and future closing time.</p>
<h3>Documents by classification</h3><p>Required evidence blocks submission when missing. Optional evidence remains visible and uploadable. Verified existing Student documents are reused automatically. Configuration freezes once applications exist.</p><div class="en-grid"><fieldset v-for="c in classifications" :key="c.value"><legend>{{ c.label }}</legend><div v-for="d in data.document_types" :key="d.id"><span>{{ d.document_name }}</span><label class="en-check"><input type="checkbox" :value="d.id" v-model="form.document_requirements[c.value].required" :disabled="busy || form.document_requirements[c.value].optional.includes(d.id)">Required</label><label class="en-check"><input type="checkbox" :value="d.id" v-model="form.document_requirements[c.value].optional" :disabled="busy || form.document_requirements[c.value].required.includes(d.id)">Optional</label></div><p v-if="!data.document_types.length">No active document types configured.</p></fieldset></div><div class="en-actions"><button :disabled="busy" type="submit">Save period</button><button :disabled="busy" type="button" class="en-secondary" @click="form=null">Cancel</button></div></form>
</template>
<form v-else class="en-card en-grid" @submit.prevent="page=1;load()"><label>Applicant name or number<input v-model="filters.search" maxlength="100" placeholder="Search applicants"></label><label>Course<select v-model="filters.course_id"><option value="">All courses</option><option v-for="c in data.courses" :key="c.id" :value="c.id">{{ c.course_name }}</option></select></label><label>Classification<select v-model="filters.classification"><option value="">All classifications</option><option v-for="c in classifications" :key="c.value" :value="c.value">{{ c.label }}</option></select></label><label>Status<select v-model="filters.status"><option value="">All statuses</option><option v-for="s in ['draft','submitted','under_review','approved','enrolled','rejected','cancelled']" :key="s" :value="s">{{ label(s) }}</option></select></label><label>Term<select v-model="filters.period_id"><option value="">All terms</option><option v-for="p in data.periods" :key="p.id" :value="p.id">{{ termLabel(p) }}</option></select></label><label>Sort<select v-model="filters.sort"><option value="newest">Newest first</option><option value="oldest">Oldest first</option></select></label><button :disabled="busy" type="submit">Apply filters</button></form>
<div class="en-card en-table"><table><thead><tr v-if="periodsPage"><th>Term</th><th>Window</th><th>State</th><th>Action</th></tr><tr v-else><th>Applicant</th><th>Course / term</th><th>Classification</th><th>Status</th><th>Action</th></tr></thead><tbody><template v-for="row in rows?.data" :key="row.id"><tr v-if="periodsPage"><td>{{ termLabel(row) }}</td><td>{{ new Date(row.opens_at).toLocaleString() }} – {{ new Date(row.closes_at).toLocaleString() }}</td><td><span class="en-badge" :data-status="row.state">{{ label(row.state) }}</span></td><td><button :disabled="busy" @click="edit(row)">Edit / open / close</button></td></tr><tr v-else><td>{{ nameOf(row) }}<br>{{ identityOf(row) }}<br><small>{{ applicantType(row) }}</small></td><td>{{ row.course?.course_name }}<br>{{ termLabel(row.period) }}</td><td><span class="en-badge">{{ label(row.classification) }}</span></td><td><span class="en-badge" :data-status="row.status">{{ label(row.status) }}</span></td><td><button :disabled="busy" @click="inspect(row)">Inspect</button></td></tr></template><tr v-if="!rows?.data?.length"><td :colspan="periodsPage?4:5">No records found.</td></tr></tbody></table></div>
<div class="en-actions"><button :disabled="busy || page<=1" @click="page--;load()">Previous</button><span>Page {{ rows?.current_page }} of {{ rows?.last_page }}</span><button :disabled="busy || page>=rows?.last_page" @click="page++;load()">Next</button></div>
</template>
<EnrollmentDialog v-if="detail && !periodsPage" labelledby="en-application-detail" :busy="busy" wide @cancel="closeDetail"><header class="en-dialog-header"><div><h2 id="en-application-detail">Application #{{ detail.id }}</h2><p>{{ nameOf(detail) }} · {{ identityOf(detail) }} · {{ applicantType(detail) }}</p></div><button type="button" :disabled="busy" aria-label="Close application details" @click="closeDetail">Close</button></header><div class="en-dialog-body"><section class="en-detail-section"><h3>Enrollment overview</h3><div class="en-grid"><p><strong>Course and curriculum</strong><br>{{ detail.course?.course_name }} · {{ detail.curriculum?.curriculum_name }} · Year {{ detail.year_level }}</p><p><strong>Term and classification</strong><br>{{ termLabel(detail.period) }} · {{ label(detail.classification) }}</p><p><strong>Application status</strong><br><span class="en-badge" :data-status="detail.status">{{ label(detail.status) }}</span></p></div><p>{{ classifications.find(c=>c.value===detail.classification)?.description }}</p></section><section class="en-detail-section"><h3>Documents</h3><p v-if="!requirements.length">No additional documents required.</p><div v-for="d in requirements" :key="d.id" class="en-actions"><span>{{ d.name }} ({{ d.required?'Required':'Optional' }}) — {{ d.attached?'Attached':d.reusable?'Verified existing record':d.required?'Missing':'Not supplied' }}</span><button v-if="d.document_id" @click="download(d)">Download {{ d.name }}</button></div></section><section class="en-detail-section"><h3>Review</h3><label>Review notes<textarea v-model="notes" maxlength="3000" :disabled="busy || !['submitted','under_review'].includes(detail.status)"></textarea></label><p>Approval completes application review. It does not assign subjects, sections, or mark the Student academically enrolled.</p><div class="en-actions"><button v-if="detail.status==='submitted'" :disabled="busy" @click="confirmation='review'">Start Review</button><button v-if="detail.status==='under_review'" :disabled="busy" @click="confirmation='approve'">Approve</button><button v-if="['submitted','under_review'].includes(detail.status)" :disabled="busy || !notes.trim()" @click="confirmation='reject'">Reject</button></div></section><EnrollmentLoad v-if="['approved','enrolled'].includes(detail.status)" :application-id="detail.id" @changed="refreshDetail"/></div></EnrollmentDialog>
<EnrollmentDialog v-if="confirmation" labelledby="en-staff-confirm" :busy="busy" @cancel="confirmation=''"><h2 id="en-staff-confirm">Confirm {{ label(confirmation) }}</h2><p>Application #{{ detail.id }} · {{ identityOf(detail) }} · {{ detail.course?.course_name }}</p><p>{{ notes }}</p><div class="en-actions"><button @click="confirmation=''">Go back</button><button @click="act">Confirm</button></div></EnrollmentDialog>
</template>
